			LOG_ERR("Unexpected read");
			return -EIO;
		}
		if (msgs[0].len != 1) {
			LOG_ERR("Unexpected msg0 length %d", msgs[0].len);
			return -EIO;
		}

		if (msgs[1].flags & I2C_MSG_WRITE) {
			LOG_ERR("Unexpected write");
			return -EIO;
