/*
 * BQ27Z746 Emulator
 */

#undef DT_DRV_COMPAT
#define DT_DRV_COMPAT ti_bq27z746

/** Static configuration for the emulator */
struct bq27z746_emul_cfg {
	/** I2C address of emulator */
	uint16_t addr;
};

/** Run-time data used by the emulator */
struct bq27z746_emul_data {
	uint16_t regs[256]; /* Assuming 8-bit register addresses */
	uint8_t manufacturer_name[32];
	uint8_t device_name[32];
	uint8_t device_chemistry[32];
};

static int emul_bq27z746_reg_write(const struct emul *target, uint8_t reg, uint16_t val)
{
	struct bq27z746_emul_data *data = target->data;

	if (reg >= ARRAY_SIZE(data->regs)) {
		LOG_ERR("Register 0x%x out of bounds", reg);
		return -EIO;
	}

	data->regs[reg] = val;
	LOG_DBG("write 0x%02x = 0x%04x", reg, val);
	return 0;
}

static int emul_bq27z746_reg_read(const struct emul *target, uint8_t reg, uint16_t *val)
{
	struct bq27z746_emul_data *data = target->data;

	if (reg >= ARRAY_SIZE(data->regs)) {
		LOG_ERR("Register 0x%x out of bounds", reg);
		return -EIO;
	}

	switch (reg) {
	case SBS_GAUGE_MANUFACTURER_ACCESS:
		*val = 1; /* Arbitrary stub value for manufacturer access */
		break;
	case SBS_GAUGE_CURRENT:
		*val = (uint16_t)-2000 / 1000; /* -2000uA -> -2mA */
		break;
	case SBS_GAUGE_AVERAGE_CURRENT:
		*val = (uint16_t)-2000 / 1000; /* -2000uA -> -2mA */
		break;
	case SBS_GAUGE_RELATIVE_STATE_OF_CHARGE:
		*val = 1;
		break;
	case SBS_GAUGE_FULL_CHARGE_CAPACITY:
		*val = 1000 / 1000; /* 1000uAh -> 1mAh */
		break;
	case SBS_GAUGE_REMAINING_CAPACITY:
		*val = 1000 / 1000; /* 1000uAh -> 1mAh */
		break;
	case SBS_GAUGE_RUN_TIME_TO_EMPTY:
		*val = 1;
		break;
	case SBS_GAUGE_RUN_TIME_TO_FULL:
		*val = 1;
		break;
	case SBS_GAUGE_TEMPERATURE:
		*val = 1; /* 1 dK */
		break;
	case SBS_GAUGE_VOLTAGE:
		*val = 1000 / 1000; /* 1000uV -> 1mV */
		break;
	case SBS_GAUGE_CYCLE_COUNT:
		*val = 1;
		break;
	case SBS_GAUGE_AT_RATE:
		*val = (uint16_t)-2;
		break;
	case SBS_GAUGE_AT_RATE_TIME_TO_EMPTY:
		*val = 1;
		break;
	case SBS_GAUGE_CHARGING_CURRENT:
		*val = 1000 / 1000; /* 1000uA -> 1mA */
		break;
	case SBS_GAUGE_CHARGING_VOLTAGE:
		*val = 1000 / 1000; /* 1000uV -> 1mV */
		break;
	case SBS_GAUGE_BATTERY_STATUS:
		*val = 1; /* Arbitrary status */
		break;
	case SBS_GAUGE_DESIGN_CAPACITY:
		*val = 1;
		break;
	case SBS_GAUGE_STATE_OF_HEALTH:
		*val = 1;
		break;
	case SBS_GAUGE_MANUFACTURER_NAME:
	case SBS_GAUGE_DEVICE_NAME:
	case SBS_GAUGE_DEVICE_CHEMISTRY:
		/* These are handled by block read, not word read.
		 * For now, return an error if read as word.
		 */
		LOG_ERR("Attempt to read block register 0x%x as word", reg);
		return -EINVAL;
	default:
		*val = data->regs[reg]; /* Return stored value for other registers */
		break;
	}
	LOG_INF("read 0x%x = 0x%x", reg, *val);

	return 0;
}

static int emul_bq27z746_block_read(const struct emul *target, uint8_t reg, uint8_t *buf, int len)
{
	struct bq27z746_emul_data *data = target->data;
	int str_len;

	switch (reg) {
	case SBS_GAUGE_MANUFACTURER_NAME:
		str_len = strlen((char *)data->manufacturer_name);
		if (len < str_len + 1) { /* +1 for length byte */
			return -ENOMEM;
		}
		buf[0] = str_len;
		memcpy(&buf[1], data->manufacturer_name, str_len);
		break;
	case SBS_GAUGE_DEVICE_NAME:
		str_len = strlen((char *)data->device_name);
		if (len < str_len + 1) {
			return -ENOMEM;
		}
		buf[0] = str_len;
		memcpy(&buf[1], data->device_name, str_len);
		break;
	case SBS_GAUGE_DEVICE_CHEMISTRY:
		str_len = strlen((char *)data->device_chemistry);
		if (len < str_len + 1) {
			return -ENOMEM;
		}
		buf[0] = str_len;
		memcpy(&buf[1], data->device_chemistry, str_len);
		break;
	default:
		LOG_ERR("Unknown block read register 0x%x", reg);
		return -EIO;
	}

	LOG_INF("block read 0x%x, len %d", reg, len);
	return 0;
}


static int bq27z746_emul_transfer_i2c(const struct emul *target, struct i2c_msg *msgs,
					 int num_msgs, int addr)
{
	int ret = 0;
	uint16_t val;
	uint8_t reg;

	__ASSERT_NO_MSG(msgs && num_msgs);

	i2c_dump_msgs_rw(target->dev, msgs, num_msgs, addr, false);

	switch (num_msgs) {
	case 1:
		if (msgs[0].flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected single-message read");
			return -EIO;
		}
		if (msgs[0].len == 0) {
			/* Zero-length write used for I2C device probing - ACK it */
			return 0;
		}
		if (msgs[0].len == 1) {
			/* Single byte write, usually setting register for subsequent read */
			reg = msgs[0].buf[0];
			/* For SBS, the register is sent with each read/write.
			 * So this case is not typical for SBS word writes.
			 * It could be a block read command.
			 * For now, assume it's a probe or a command that doesn't write data.
			 */
			LOG_DBG("Single byte write: 0x%02x", reg);
			return 0;
		}
		if (msgs[0].len == 3) {
			/* Word write (reg + 2 bytes data) */
			reg = msgs[0].buf[0];
			val = sys_get_le16(&msgs[0].buf[1]); /* SBS uses little-endian for words */
			ret = emul_bq27z746_reg_write(target, reg, val);
		} else {
			LOG_ERR("Unexpected msg0 length %d", msgs[0].len);
			return -EIO;
		}
		break;
	case 2:
		if (msgs[0].flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected read in first message");
			return -EIO;
		}
		if (msgs[0].len != 1) {
			LOG_ERR("Unexpected msg0 length %d", msgs[0].len);
			return -EIO;
		}
		reg = msgs[0].buf[0];

		/* Now process the 'read' or 'write' part of the message */
		msgs++;
		if (msgs[0].flags & I2C_MSG_READ) {
			if (msgs[0].len == 2) {
				/* Word read (2 bytes data) */
				ret = emul_bq27z746_reg_read(target, reg, &val);
				if (ret) {
					return ret;
				}
				sys_put_le16(val, msgs[0].buf); /* SBS uses little-endian for words */
			} else if (msgs[0].len > 2) {
				/* Block read (length byte + data) */
				ret = emul_bq27z746_block_read(target, reg, msgs[0].buf, msgs[0].len);
			} else {
				LOG_ERR("Unexpected msg1 read length %d", msgs[0].len);
				return -EIO;
			}
		} else {
			/* Word write (2 bytes data) */
			if (msgs[0].len != 2) {
				LOG_ERR("Unexpected msg1 write length %d", msgs[0].len);
				return -EIO;
			}
			val = sys_get_le16(msgs[0].buf); /* SBS uses little-endian for words */
			ret = emul_bq27z746_reg_write(target, reg, val);
		}
		break;
	default:
		LOG_ERR("Invalid number of messages: %d", num_msgs);
		return -EIO;
	}

	return ret;
}

static const struct i2c_emul_api bq27z746_emul_api_i2c = {
	.transfer = bq27z746_emul_transfer_i2c,
};

static int emul_bq27z746_init(const struct emul *target, const struct device *parent)
{
	ARG_UNUSED(parent);
	struct bq27z746_emul_data *data = target->data;

